/**
 * Emit the given run event to HTTP backend. The method will return successfully after the run
 * event has been emitted, regardless of any exceptions thrown by the HTTP backend.
 *
 * @param runEvent The run event to emit.
 */
public void emit(@NonNull OpenLineage.RunEvent runEvent) {
  emitRunEvent(runEvent, () -> transport.emit(runEvent));
}

/**
 * Emit the given run event with a bounded wait when supported by the configured transport.
 *
 * <p>Transports that do not support bounded delivery acknowledgement may fall back to regular
 * asynchronous emit semantics.
 *
 * @param runEvent The run event to emit.
 * @param timeout Maximum time to wait for transports that support bounded delivery.
 */
public void emit(@NonNull OpenLineage.RunEvent runEvent, @NonNull Duration timeout) {
  emitRunEvent(runEvent, () -> transport.emit(runEvent, timeout));
}

private void emitRunEvent(@NonNull OpenLineage.RunEvent runEvent, Runnable emit) {
  if (log.isDebugEnabled()) {
    log.debug(
        "OpenLineageClient will emit lineage event: {}", OpenLineageClientUtils.toJson(runEvent));
  }
  if (circuitBreaker.isPresent() && circuitBreaker.get().currentState().isClosed()) {
    engagedCircuitBreaker.set(1);
    log.warn("OpenLineageClient disabled with circuit breaker");
    return;
  } else {
    engagedCircuitBreaker.set(0);
  }
  emitStart.increment();
  emitTime.record(emit);
  emitComplete.increment();

private static CloseableHttpClient withTimeout(HttpConfig httpConfig) {
  int timeoutMs;
  if (httpConfig.getTimeoutInMillis() != null) {
    timeoutMs = httpConfig.getTimeoutInMillis();
  } else {
    // default one
    timeoutMs = 5000;
  }
  Timeout timeout = Timeout.ofMilliseconds(timeoutMs);

  // A unix:// URL means the target is a Unix Domain Socket endpoint (e.g. one exposed on a
  // Kubernetes node). Apache HttpClient can't dial a UDS directly, so build a client whose
  // connection socket factory tunnels over the socket; the request itself uses a placeholder
  // http://localhost URL (see getUri).
  if (isUnixSocket(httpConfig)) {
    return withUnixSocket(httpConfig, timeout);
  }

  PoolingHttpClientConnectionManagerBuilder connectionManagerBuilder =
      PoolingHttpClientConnectionManagerBuilder.create()
          .setDefaultSocketConfig(SocketConfig.custom().setSoTimeout(timeout).build())
          .setPoolConcurrencyPolicy(PoolConcurrencyPolicy.STRICT)
          .setConnPoolPolicy(PoolReusePolicy.LIFO)
          .setDefaultConnectionConfig(
              ConnectionConfig.custom()
                  .setSocketTimeout(timeout)
                  .setConnectTimeout(timeout)
                  .setTimeToLive(timeout)
                  .build());

  if (httpConfig.getSslContextConfig() != null) {
    SSLContext sslContext = getSSLContext(httpConfig.getSslContextConfig());
    if (sslContext != null) {
      log.info("SSLContext set up successfully");
      DefaultClientTlsStrategy tlsStrategy = new DefaultClientTlsStrategy(sslContext);
      connectionManagerBuilder.setTlsSocketStrategy(tlsStrategy);
    } else {
      log.warn("SSLContext configured but unable to set up");
    }
  }

  RequestConfig requestConfig =
      RequestConfig.custom()
          .setConnectionRequestTimeout(timeout)
          .setResponseTimeout(timeout)
          .build();

  HttpClientBuilder builder =
      HttpClientBuilder.create()
          .setDefaultRequestConfig(requestConfig)
          .setConnectionManager(connectionManagerBuilder.build());

@Override
public void emit(@NonNull OpenLineage.RunEvent runEvent) {
  emit(OpenLineageClientUtils.toJson(runEvent));
}

@Override
public void emit(@NonNull OpenLineage.DatasetEvent datasetEvent) {
